/* Reset & Base Variables */
:root {
  --color-bg: #f3f6fa;
  --color-surface: #ffffff;
  --color-surface-hover: #f8fafc;
  --color-primary: #2563eb;
  --color-primary-light: #eff6ff;
  --color-primary-dark: #1d4ed8;
  --color-primary-border: #93c5fd;
  --color-accent: #06b6d4;
  --color-accent-light: #ecfeff;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;
  --color-border: #e2e8f0;
  --color-border-focus: #3b82f6;
  --color-success: #10b981;
  --color-success-light: #d1fae5;
  --color-success-text: #065f46;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --shadow-active: 0 0 0 3px rgba(37, 99, 235, 0.2);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans JP", sans-serif;

  /* Card specific colors */
  --card-active-bg-start: #ffffff;
  --card-active-bg-end: #eff6ff;
  --badge-active-bg: #dbeafe;
  --badge-active-text: #1d4ed8;
  --comparison-bg-start: #ffffff;
  --comparison-bg-end: #f0fdf4;
  --comparison-border: #bbf7d0;
  --comparison-title: #15803d;
  --comparison-icon-bg: #dcfce7;
  --toast-bg: rgba(15, 23, 42, 0.92);
  --toast-text: #ffffff;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #0f172a;
    --color-surface: #1e293b;
    --color-surface-hover: #334155;
    --color-primary: #3b82f6;
    --color-primary-light: #1e3a8a;
    --color-primary-dark: #60a5fa;
    --color-primary-border: #3b82f6;
    --color-accent: #38bdf8;
    --color-accent-light: #082f49;
    --color-text-main: #f8fafc;
    --color-text-muted: #94a3b8;
    --color-text-light: #64748b;
    --color-border: #334155;
    --color-border-focus: #60a5fa;
    --color-success: #34d399;
    --color-success-light: #064e3b;
    --color-success-text: #a7f3d0;
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
    --shadow-active: 0 0 0 3px rgba(96, 165, 250, 0.3);

    --card-active-bg-start: #1e293b;
    --card-active-bg-end: #172554;
    --badge-active-bg: #1e3a8a;
    --badge-active-text: #93c5fd;
    --comparison-bg-start: #1e293b;
    --comparison-bg-end: #064e3b;
    --comparison-border: #047857;
    --comparison-title: #4ade80;
    --comparison-icon-bg: #065f46;
    --toast-bg: rgba(30, 41, 59, 0.95);
    --toast-text: #f8fafc;
  }
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* App Container */
.app-container {
  width: 100%;
  max-width: 960px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 40px 24px 80px;
  }
}

/* Header */
.header {
  text-align: center;
  margin-bottom: 28px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

@media (min-width: 640px) {
  .header-title {
    font-size: 2.25rem;
  }
}

.header-desc {
  margin-top: 8px;
  font-size: 0.95rem;
  color: var(--color-text-muted);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* Main Layout */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Input Card */
.input-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition-normal);
}

@media (min-width: 640px) {
  .input-card {
    padding: 28px;
  }
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.unit-label {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.clear-btn {
  background: transparent;
  border: none;
  font-size: 0.85rem;
  color: var(--color-text-light);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.clear-btn:hover {
  color: #ef4444;
  background-color: rgba(239, 68, 68, 0.15);
}

.clear-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #ef4444;
}

.input-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (min-width: 520px) {
  .input-wrapper {
    flex-direction: row;
    align-items: center;
  }
}

.number-input {
  flex: 1;
  font-size: 1.5rem;
  font-weight: 700;
  font-family: inherit;
  color: var(--color-text-main);
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast);
  min-width: 0;
  width: 100%;
}

.number-input:focus-visible,
.number-input:focus {
  background-color: var(--color-surface);
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-active);
}

.number-input::placeholder {
  color: var(--color-text-light);
  font-weight: 400;
}

.unit-select {
  font-size: 1.05rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--color-text-main);
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  outline: none;
  cursor: pointer;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast);
  min-width: 170px;
}

.unit-select:focus-visible,
.unit-select:focus {
  background-color: var(--color-surface);
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-active);
}

/* Preset Section */
.preset-section {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px dashed var(--color-border);
}

.preset-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: 10px;
}

.preset-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.preset-tag {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--color-text-main);
  cursor: pointer;
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.preset-tag:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-border);
  color: var(--color-primary-dark);
  transform: translateY(-1px);
}

.preset-tag:focus-visible {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-active);
}

.preset-tag:active {
  transform: translateY(0);
}

/* Results Section */
.results-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.results-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.results-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.copy-all-btn {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-fast);
}

.copy-all-btn:hover {
  color: var(--color-primary-dark);
  border-color: var(--color-primary-border);
  background-color: var(--color-primary-light);
}

.copy-all-btn:focus-visible {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-active);
}

/* Result Grid & Cards */
.result-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

@media (min-width: 560px) {
  .result-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 860px) {
  .result-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.result-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
  overflow: hidden;
  outline: none;
}

.result-card:hover {
  border-color: var(--color-primary-border);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.result-card:focus-visible {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px var(--color-border-focus);
  transform: translateY(-2px);
}

.result-card-active {
  background: linear-gradient(145deg, var(--card-active-bg-start), var(--card-active-bg-end));
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.18);
}

.result-card-active:focus-visible {
  box-shadow: 0 0 0 3px var(--color-primary), 0 4px 12px rgba(37, 99, 235, 0.25);
}

.result-card-active::after {
  content: "基準単位";
  position: absolute;
  top: 8px;
  right: 8px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--badge-active-text);
  background-color: var(--badge-active-bg);
  padding: 2px 6px;
  border-radius: var(--radius-full);
}

.result-header {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.result-unit-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.result-unit-symbol {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.result-value-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.result-value {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-text-main);
  word-break: break-all;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.result-card-active .result-value {
  color: var(--color-primary-dark);
}

.copy-btn {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.copy-btn:hover {
  background-color: var(--color-surface);
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.copy-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-primary);
}

.copied-badge {
  background-color: var(--color-success-light);
  color: var(--color-success-text);
  border: 1px solid var(--color-success);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  animation: badgePop 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

@keyframes badgePop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

/* Comparison Card */
.comparison-card {
  background: linear-gradient(135deg, var(--comparison-bg-start), var(--comparison-bg-end));
  border: 1px solid var(--comparison-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (min-width: 640px) {
  .comparison-card {
    padding: 24px;
  }
}

.comparison-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--comparison-title);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 6px;
}

.comparison-visual {
  display: flex;
  align-items: center;
  gap: 16px;
}

.comparison-icon {
  font-size: 2.4rem;
  line-height: 1;
  background-color: var(--comparison-icon-bg);
  padding: 12px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.comparison-text {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text-main);
  line-height: 1.5;
}

/* Toast Notification */
.toast-notification {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--toast-bg);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--toast-text);
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  z-index: 1000;
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  animation: toastFadeIn 0.25s ease-out;
}

@keyframes toastFadeIn {
  from {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

export type UnitKey = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'foot' | 'yard';

export type UnitSystem = 'metric' | 'imperial';

export interface UnitDefinition {
  key: UnitKey;
  label: string;
  symbol: string;
  toMeters: number;
  description: string;
  system: UnitSystem;
}

export interface ConversionResult {
  key: UnitKey;
  label: string;
  symbol: string;
  value: number;
  formattedValue: string;
}

export interface ComparisonItem {
  name: string;
  lengthInMeters: number;
  icon: string;
}

export interface ComparisonMatchResult {
  item: ComparisonItem;
  ratio: number;
  displayText: string;
}

export interface PresetItem {
  name: string;
  value: number;
  unit: UnitKey;
  icon: string;
}

import { UnitKey, UnitDefinition, ConversionResult, ComparisonItem, ComparisonMatchResult } from '../types';

