export function formatLength(value: number): string {
  if (value === 0) return '0';
  if (!Number.isFinite(value) || Number.isNaN(value)) return '0';

  const abs = Math.abs(value);

  if (abs >= 1e12 || (abs < 1e-6 && abs > 0)) {
    const rawExp = value.toExponential(4);
    const [mantissa, exponent] = rawExp.split('e');
    const cleanMantissa = parseFloat(mantissa).toString();
    const cleanExponent = exponent.replace('+', '');
    return `${cleanMantissa}e${cleanExponent}`;
  }

  // 浮動小数点の丸め誤差を考慮した有効桁数の調整
  let formatted: string;
  if (abs >= 10000) {
    formatted = Number(value.toFixed(2)).toLocaleString('en-US', {
      maximumFractionDigits: 4,
      minimumFractionDigits: 0
    });
  } else if (abs >= 100) {
    formatted = Number(value.toFixed(4)).toLocaleString('en-US', {
      maximumFractionDigits: 4,
      minimumFractionDigits: 0
    });
  } else if (abs >= 1) {
    formatted = Number(value.toFixed(5)).toLocaleString('en-US', {
      maximumFractionDigits: 5,
      minimumFractionDigits: 0
    });
  } else {
    formatted = Number(value.toFixed(6)).toLocaleString('en-US', {
      maximumFractionDigits: 6,
      minimumFractionDigits: 0
    });
  }

  return formatted;
}

export function calculateConversions(inputValue: number, fromUnit: UnitKey): ConversionResult[] {
  // 長さとしてのサニタイズ（負数は0として処理）
  const sanitizedValue = Math.max(0, inputValue);

  const currentUnit = UNITS.find((u) => u.key === fromUnit);
  if (!currentUnit || Number.isNaN(sanitizedValue)) {
    return UNITS.map((unit) => ({
      key: unit.key,
      label: unit.label,
      symbol: unit.symbol,
      value: 0,
      formattedValue: '0'
    }));
  }

  // 入力値をメートルに換算
  const lengthInMeters = sanitizedValue * currentUnit.toMeters;

  return UNITS.map((unit) => {
    const convertedValue = lengthInMeters / unit.toMeters;
    return {
      key: unit.key,
      label: unit.label,
      symbol: unit.symbol,
      value: convertedValue,
      formattedValue: formatLength(convertedValue)
    };
  });
}

export function getClosestComparison(lengthInMeters: number): ComparisonMatchResult | null {
  // 長さとしてのサニタイズ（0以下や無効値は比較対象外）
  if (lengthInMeters <= 0 || !Number.isFinite(lengthInMeters)) {
    return null;
  }

  const validLength = lengthInMeters;

  let bestItem = COMPARISON_ITEMS[0];
  let minRatioDiff = Infinity;

  for (const item of COMPARISON_ITEMS) {
    const ratio = validLength / item.lengthInMeters;
    // 対数目盛り的な近さ (1に近いほど等倍)
    const diff = Math.abs(Math.log10(ratio));
    if (diff < minRatioDiff) {
      minRatioDiff = diff;
      bestItem = item;
    }
  }

  const ratio = validLength / bestItem.lengthInMeters;
  let ratioString: string;

  if (ratio >= 0.95 && ratio <= 1.05) {
    ratioString = 'ほぼ同じ長さ';
  } else if (ratio > 1) {
    ratioString = `約 ${ratio >= 100 ? Math.round(ratio).toLocaleString() : Number(ratio.toFixed(1))} 個分`;
  } else {
    const fraction = 1 / ratio;
    ratioString = `約 1/${fraction >= 100 ? Math.round(fraction).toLocaleString() : Number(fraction.toFixed(1))}`;
  }

  const displayText = `${bestItem.name} の ${ratioString}`;

  return {
    item: bestItem,
    ratio,
    displayText
  };
}

import { UnitKey, ConversionResult } from '../types';

interface UnitResultListProps {
  results?: ConversionResult[];
  activeUnit: UnitKey;
  onSelectUnit?: (unit: UnitKey) => void;
  onCopy?: (text: string, label: string) => void;
  copiedKey: string | null;
}

export default function UnitResultList({
  results = [],
  activeUnit,
  onSelectUnit,
  onCopy,
  copiedKey
}: UnitResultListProps) {
  const handleSelect = (unitKey: UnitKey) => {
    onSelectUnit?.(unitKey);
  };

  const handleCopyClick = (result: ConversionResult) => {
    onCopy?.(`${result.formattedValue} ${result.symbol}`, result.label);
  };

  return (
    <div className="result-grid">
      {results.map((result) => {
        const isActive = result.key === activeUnit;
        const isCopied = copiedKey === result.key;
        const cardClassName = isActive ? 'result-card result-card-active' : 'result-card';

        return (
          <div
            key={result.key}
            className={cardClassName}
            onClick={() => handleSelect(result.key)}
            title={isActive ? '現在の基準単位です' : 'クリックして基準単位に設定'}
          >
            <div className="result-header">
              <span className="result-unit-name">{result.label}</span>
              <span className="result-unit-symbol">({result.symbol})</span>
            </div>

            <div className="result-value-row">
              <span
                className="result-value"
                role="button"
                tabIndex={0}
                aria-pressed={isActive}
                aria-label={`${result.label}: ${result.formattedValue} ${result.symbol}${isActive ? '（基準単位）' : '。クリックして基準単位に設定'}`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleSelect(result.key);
                  }
                }}
              >
                {result.formattedValue}
              </span>
              {isCopied ? (
                <span className="copied-badge" role="status" aria-live="polite">
                  ✓ コピー済
                </span>
              ) : (
                <button
                  type="button"
                  className="copy-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleCopyClick(result);
                  }}
                  aria-label={`${result.label}の値（${result.formattedValue} ${result.symbol}）をコピー`}
                >
                  コピー
                </button>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { UnitKey, PresetItem } from './types';
import { UNITS, calculateConversions, getClosestComparison } from './utils/converter';
import UnitResultList from './components/UnitResultList';

const PRESETS: PresetItem[] = [
  { name: 'スマホ画面', value: 6.1, unit: 'inch', icon: '📱' },
  { name: '1円玉直径', value: 20, unit: 'mm', icon: '🪙' },
  { name: 'A4用紙長辺', value: 29.7, unit: 'cm', icon: '📄' },
  { name: '1フィート', value: 1, unit: 'foot', icon: '📏' },
  { name: '成人平均身長', value: 170, unit: 'cm', icon: '🧍' },
  { name: '東京タワー', value: 333, unit: 'm', icon: '🗼' },
  { name: '富士山標高', value: 3776, unit: 'm', icon: '🗻' },
  { name: 'フルマラソン', value: 42.195, unit: 'km', icon: '🏃' }
];

export default function App() {
  const [inputValue, setInputValue] = useState<string>('170');
  const [selectedUnit, setSelectedUnit] = useState<UnitKey>('cm');
  const [copiedKey, setCopiedKey] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const numericValue = useMemo(() => {
    const parsed = parseFloat(inputValue);
    return Number.isFinite(parsed) ? parsed : 0;
  }, [inputValue]);

  const isNegative = useMemo(() => {
    const trimmed = inputValue.trim();
    return trimmed.startsWith('-') || numericValue < 0;
  }, [inputValue, numericValue]);

  const conversionResults = useMemo(() => {
    return calculateConversions(numericValue, selectedUnit);
  }, [numericValue, selectedUnit]);

  // 身近な物との比較情報（メートル基準）
  const comparison = useMemo(() => {
    if (isNegative || numericValue <= 0) return null;
    const currentUnitDef = UNITS.find((u) => u.key === selectedUnit);
    if (!currentUnitDef) return null;
    const lengthInMeters = numericValue * currentUnitDef.toMeters;
    return getClosestComparison(lengthInMeters);
  }, [isNegative, numericValue, selectedUnit]);

  // トーストタイマー
  useEffect(() => {
    if (!toastMessage) return;
    const timer = setTimeout(() => {
      setToastMessage(null);
    }, 2400);
    return () => clearTimeout(timer);
  }, [toastMessage]);

  const showToast = (message: string) => {
    setToastMessage(message);
  };

  const handleCopySingle = (text: string, label: string) => {
    const targetUnit = UNITS.find((u) => u.label === label);
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(text).catch(() => {});
    }
    if (targetUnit) {
      setCopiedKey(targetUnit.key);
      setTimeout(() => setCopiedKey(null), 1800);
    }
    showToast(`${label}「${text}」をコピーしました`);
  };

  const handleCopyAll = () => {
    if (conversionResults.length === 0) return;
    const textAll = conversionResults
      .map((item) => `${item.label} (${item.symbol}): ${item.formattedValue}`)
      .join('\n');

    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(textAll).catch(() => {});
    }
    showToast('すべての単位の換算結果をコピーしました');
  };

  const handleSelectUnit = (unitKey: UnitKey) => {
    const targetResult = conversionResults.find((r) => r.key === unitKey);
    setSelectedUnit(unitKey);
    if (targetResult && numericValue !== 0) {
      // 生の数値から文字列を生成して安全に設定
      const nextValue = targetResult.value.toString();
      setInputValue(nextValue);
    }
  };

  const handleApplyPreset = (preset: PresetItem) => {
    setSelectedUnit(preset.unit);
    setInputValue(preset.value.toString());
    showToast(`プリセット「${preset.name}」を適用しました`);
  };

  const handleClear = () => {
    setInputValue('0');
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // 数値、マイナス、小数点、指数表記（e/E, + -）を許容
    if (/^-?\d*\.?\d*(?:[eE][+-]?\d*)?$/i.test(val)) {
      setInputValue(val);
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">
          <span>📏</span> 長さ単位変換ツール
        </h1>
        <p className="header-desc">
          ミリメートル・センチ・メートル・キロ・インチ・フィート・ヤードをリアルタイムに相互換算します
        </p>
      </header>

      <main className="main-layout">
        {/* 入力カード */}
        <section className="input-card">
          <div className="input-group">
            <div className="label-row">
              <span className="unit-label">変換元の値と単位</span>
              <button
                type="button"
                className="clear-btn"
                onClick={handleClear}
                title="値を0にリセット"
              >
                クリア
              </button>
            </div>

            <div className="input-wrapper">
              <input
                type="text"
                inputMode="decimal"
                className="number-input"
                placeholder="数値を入力..."
                value={inputValue}
                onChange={handleInputChange}
                aria-label="長さを入力"
              />

              <select
                className="unit-select"
                value={selectedUnit}
                onChange={(e) => setSelectedUnit(e.target.value as UnitKey)}
                aria-label="単位を選択"
              >
                {UNITS.map((unit) => (
                  <option key={unit.key} value={unit.key}>
                    {unit.label} ({unit.symbol})
                  </option>
                ))}
              </select>
            </div>

            {isNegative && (
              <div style={{ color: '#ef4444', fontSize: '0.85rem', fontWeight: 600 }}>
                ⚠️ 正の数値を入力してください（長さは0以上の数値で換算されます）
              </div>
            )}
          </div>

          {/* プリセットタグ一覧 */}
          <div className="preset-section">
            <div className="preset-title">日常の長さプリセットから選ぶ:</div>
            <div className="preset-tags">
              {PRESETS.map((preset) => (
                <button
                  key={preset.name}
                  type="button"
                  className="preset-tag"
                  onClick={() => handleApplyPreset(preset)}
                >
                  <span>{preset.icon}</span>
                  <span>{preset.name} ({preset.value}{preset.unit === 'inch' ? 'in' : preset.unit === 'foot' ? 'ft' : preset.unit})</span>
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* 身近なものとの比較カード */}
        {comparison && (
          <section className="comparison-card">
            <div className="comparison-title">
              <span>💡</span> 身近なスケールと比較
            </div>
            <div className="comparison-visual">
              <div className="comparison-icon">{comparison.item.icon}</div>
              <div className="comparison-text">{comparison.displayText}</div>
            </div>
          </section>
        )}

        {/* 換算結果一覧セクション */}
        <section className="results-section">
          <div className="results-header">
            <h2 className="results-title">一括換算結果</h2>
            <button
              type="button"
              className="copy-all-btn"
              onClick={handleCopyAll}
              title="全単位の換算結果をまとめてクリップボードにコピー"
            >
              📋 すべてコピー
            </button>
          </div>

          <UnitResultList
            results={conversionResults}
            activeUnit={selectedUnit}
            onSelectUnit={handleSelectUnit}
            onCopy={handleCopySingle}
            copiedKey={copiedKey}
          />
        </section>
      </main>

      {/* コピー完了・プリセット適用トースト通知 */}
      {toastMessage && (
        <div className="toast-notification" role="status" aria-live="polite">
          <span>✓</span>
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  );
}
